import pathlib,json,urllib.request
p=pathlib.Path('E:/PCControlAutonomyR41/data/r45-coordinator.json')
d=json.loads(p.read_text('utf8')) if p.exists() else {}
errors={}
for route in ('/api/health','/api/status','/api/supervisor-watchdog/agent-assignments'):
 try:
  with urllib.request.urlopen('http://127.0.0.1:17448'+route,timeout=3) as f:
   payload=json.load(f)
  errors[route]={'reachable':True,'status':payload.get('state'),'total':len(payload.get('assignments',[]))}
 except Exception as e:errors[route]={'reachable':False,'error':type(e).__name__}
print(json.dumps({'r45LastError':str(d.get('lastError',''))[:260],'endpoints':errors,'readOnly':True}))
